#include <bits/stdc++.h>
using namespace std;

std::string py_input() { std::string s; if (!std::getline(std::cin, s)) throw std::runtime_error("input failed"); return s; }

int py_floor_div(int a, int b) { if (b == 0) throw std::runtime_error("division by zero"); int q = a / b, r = a % b; return q - ((r != 0) && ((r < 0) != (b < 0))); }

int main() {
    long long a = std::stoll(py_input());
    long long b = std::stoll(py_input());
    std::cout << py_floor_div(a, b) << std::endl;
    return 0;
}

