nested_conditions.ast_cpp:
#include <bits/stdc++.h>
using namespace std;

std::string py_input() { std::string s; if (!std::getline(std::cin, s)) throw std::runtime_error("input failed"); return s; }

int main() {
    long long n = std::stoll(py_input());
    if (n > 0) {
        if (n % 2 == 0) {
            std::cout << "positive even" << std::endl;
        } else {
            std::cout << "positive odd" << std::endl;
        }
    } else {
        std::cout << "non-positive" << std::endl;
    }
    return 0;
}

